('q_csdl_01_s1_02', 'moc_csdl_01_01', 1, 'NHO', 'TRAC_NGHIEM_4', 'Định nghĩa về Thông tin (Information) có điểm khác biệt cốt lõi nào so với Dữ liệu?', 'Dữ liệu đã được xử lý và đặt trong ngữ cảnh có ý nghĩa rõ ràng.', 'Dữ liệu thô thu thập từ các thiết bị cảm biến mà chưa qua phân tích.', 'Tập hợp các bit 0 và 1 lưu trữ dưới dạng tệp nhị phân trên đĩa.', 'Các phần mềm ứng dụng được cài đặt trên hệ điều hành máy tính.', 0, NULL, 'Thông tin là dữ liệu đã được xử lý, tổ chức và đặt vào ngữ cảnh có ý nghĩa thực tiễn.', 1),
('q_csdl_01_s1_03', 'moc_csdl_01_01', 1, 'NHO', 'TRAC_NGHIEM_4', 'Hệ Quản trị Cơ sở Dữ liệu (DBMS) được định nghĩa là loại phần mềm gì?', 'Phần mềm ứng dụng dành riêng cho việc vẽ sơ đồ và thiết kế giao diện đồ họa.', 'Phần mềm hệ thống cho phép định nghĩa, tạo lập, lưu trữ và quản trị dữ liệu.', 'Phần mềm diệt virus kiểm soát an toàn kết nối mạng giữa các máy chủ từ xa.', 'Hệ điều hành quản lý việc phân phối bộ nhớ và tiến trình của vi xử lý CPU.', 1, NULL, 'DBMS là phần mềm hệ thống cung cấp các dịch vụ định nghĩa, lưu trữ, truy vấn và bảo mật CSDL.', 1),
('q_csdl_01_s1_04', 'moc_csdl_01_01', 1, 'NHO', 'TRAC_NGHIEM_4', 'Kiến trúc 3 mức trừu tượng ANSI/SPARC bao gồm những mức nào?', 'Mức Ngoài (External), Mức Quan niệm (Conceptual), Mức Trong (Internal).', 'Mức Phần cứng (Hardware), Mức Hệ điều hành (OS), Mức Ứng dụng (App).', 'Mức Khách (Client), Mức Máy chủ (Server), Mức Đám mây (Cloud storage).', 'Mức Bảng (Table), Mức Hàng (Row/Tuple), Mức Cột (Column/Attribute).', 0, NULL, 'Kiến trúc ANSI/SPARC gồm 3 mức: Mức Ngoài (Khung nhìn), Mức Quan niệm (Logic) và Mức Trong (Vật lý).', 1),
('q_csdl_01_s1_05', 'moc_csdl_01_01', 1, 'NHO', 'DIEN_TU', 'Chọn từ thích hợp từ ngân hàng từ bên dưới để điền vào chỗ trống:', NULL, NULL, NULL, NULL, NULL, '{"sentence_template":"Hệ Quản trị Cơ sở Dữ liệu cung cấp cơ chế kiểm soát truy cập đồng thời để bảo đảm tính {blank} của dữ liệu khi nhiều người cùng thao tác.","blank_answer":"nhất quán","options":["nhất quán","phức tạp","vật lý","dư thừa"]}', 'Kiểm soát đồng thời bảo đảm tính nhất quán (Consistency) của dữ liệu.', 1),
('q_csdl_01_s1_06', 'moc_csdl_01_01', 1, 'NHO', 'DIEN_TU', 'Chọn từ thích hợp từ ngân hàng từ bên dưới để điền vào chỗ trống:', NULL, NULL, NULL, NULL, NULL, '{"sentence_template":"Trong kiến trúc ANSI/SPARC, mức {blank} mô tả toàn bộ cấu trúc logic của cơ sở dữ liệu mà không phụ thuộc vào thiết bị lưu trữ.","blank_answer":"quan niệm","options":["quan niệm","vật lý","ngoài","phần cứng"]}', 'Mức quan niệm (Conceptual level) đặc tả toàn bộ thực thể, thuộc tính và mối quan hệ logic của tổ chức.', 1),
('q_csdl_01_s1_07', 'moc_csdl_01_01', 1, 'NHO', 'NOI_CAP', 'Hãy nối các khái niệm trong kiến trúc CSDL với đặc trưng cốt lõi:', NULL, NULL, NULL, NULL, NULL, '{"pairs":[{"left":"Mức Ngoài (External)","right":"Góc nhìn dữ liệu riêng cho từng nhóm ứng dụng"},{"left":"Mức Quan niệm (Conceptual)","right":"Mô tả cấu trúc logic toàn diện của tổ chức"},{"left":"Mức Trong (Internal)","right":"Đặc tả cấu trúc lưu trữ và phân vùng trên đĩa"},{"left":"Độc lập Dữ liệu Logic","right":"Đổi lược đồ quan niệm mà không sửa ứng dụng"}]}', 'Mỗi mức trong ANSI/SPARC đảm bảo tính trừu tượng và độc lập dữ liệu đa tầng.', 1),
('q_csdl_01_s1_08', 'moc_csdl_01_01', 1, 'NHO', 'SAP_XEP_CAU', 'Chạm vào các thẻ từ theo đúng thứ tự để tạo thành định nghĩa chuẩn xác:', NULL, NULL, NULL, NULL, NULL, '{"prompt":"Ghép định nghĩa về Độc lập Dữ liệu Vật lý:","correct_order":["Độc lập dữ liệu vật lý","là khả năng","thay đổi cấu trúc lưu trữ đĩa","mà không làm đổi","lược đồ quan niệm"],"distractors":["làm hỏng ứng dụng","xóa hết dữ liệu"]}', 'Độc lập dữ liệu vật lý cho phép thay đổi phần cứng, chỉ mục, khối đĩa mà không ảnh hưởng lược đồ logic.', 1),
('q_csdl_01_s1_09', 'moc_csdl_01_01', 1, 'NHO', 'TRAC_NGHIEM_4', 'Ai là nhà khoa học máy tính đề xuất Mô hình Dữ liệu Quan hệ vào năm 1970 tại IBM?', 'Edgar Frank Codd (E. F. Codd).', 'Alan Mathison Turing.', 'Donald Ervin Knuth.', 'Tim Berners-Lee.', 0, NULL, 'E. F. Codd đề xuất mô hình quan hệ dựa trên lý thuyết tập hợp toán học vào năm 1970.', 1),
('q_csdl_01_s1_10', 'moc_csdl_01_01', 1, 'NHO', 'DIEN_TU', 'Chọn từ thích hợp từ ngân hàng từ bên dưới để điền vào chỗ trống:', NULL, NULL, NULL, NULL, NULL, '{"sentence_template":"Cơ sở dữ liệu được lưu trữ trên các thiết bị bộ nhớ {blank} để dữ liệu không bị mất đi khi mất nguồn điện.","blank_answer":"phụ (thứ cấp)","options":["phụ (thứ cấp)","RAM tạm thời","cache CPU","thanh ghi"]}', 'Bộ nhớ phụ (Secondary storage như HDD, SSD) có tính bền vững (Non-volatile).', 1),
('q_csdl_01_s2_01', 'moc_csdl_01_01', 2, 'HIEU', 'TRAC_NGHIEM_4', 'Tại sao mô hình hệ thống tập tin (File System) lại dễ dẫn đến tình trạng không nhất quán dữ liệu (Data Inconsistency)?', 'Do dữ liệu bị trùng lặp ở nhiều tệp khác nhau nhưng không được đồng bộ khi cập nhật.', 'Do dung lượng tập tin luôn bị giới hạn dưới mức dung lượng khả dụng của ổ đĩa cứng.', 'Do hệ điều hành từ chối cho phép nhiều chương trình cùng thực thi tại một thời điểm.', 'Do tốc độ xung nhịp của bộ vi xử lý máy tính không đáp ứng kịp các truy vấn phức tạp.', 0, NULL, 'Trùng lặp dữ liệu (Redundancy) dẫn đến việc khi sửa ở tệp này nhưng quên sửa ở tệp khác gây mất nhất quán.', 2),
('q_csdl_01_s2_02', 'moc_csdl_01_01', 2, 'HIEU', 'TRAC_NGHIEM_4', 'Phát biểu nào sau đây phân biệt ĐÚNG NHẤT giữa Mức Quan niệm và Mức Khung nhìn (Mức ngoài)?', 'Mức Quan niệm là toàn cảnh dữ liệu duy nhất; Mức Khung nhìn là các góc nhìn cục bộ.', 'Mức Quan niệm do người dùng cuối điều chỉnh; Mức Khung nhìn do quản trị viên cấu hình.', 'Mức Quan niệm lưu dữ liệu dưới dạng nhị phân; Mức Khung nhìn lưu dưới dạng chuỗi ký tự.', 'Mức Quan niệm phụ thuộc vào thiết bị đĩa; Mức Khung nhìn độc lập hoàn toàn với máy tính.', 0, NULL, 'Mỗi hệ thống chỉ có một mức quan niệm mô tả toàn bộ tổ chức, nhưng có thể có vô số khung nhìn mức ngoài.', 2),
('q_csdl_01_s2_03', 'moc_csdl_01_01', 2, 'HIEU', 'DIEN_TU', 'Chọn từ thích hợp từ ngân hàng từ bên dưới để điền vào chỗ trống:', NULL, NULL, NULL, NULL, NULL, '{"sentence_template":"Khi người quản trị thêm một cột mới vào bảng mà không làm ảnh hưởng ứng dụng hiện có, điều đó thể hiện tính độc lập dữ liệu {blank}.","blank_answer":"logic","options":["logic","vật lý","phần cứng","mạng"]}', 'Thêm cột vào bảng là sửa đổi ở mức quan niệm, không ảnh hưởng mức ngoài là độc lập logic.', 2),
('q_csdl_01_s2_04', 'moc_csdl_01_01', 2, 'NHO', 'NOI_CAP', 'Nối vai trò của các đối tượng sử dụng hệ thống CSDL:', NULL, NULL, NULL, NULL, NULL, '{"pairs":[{"left":"Quản trị viên CSDL (DBA)","right":"Cấp quyền, sao lưu, phục hồi và tối ưu hiệu năng"},{"left":"Nhà thiết kế CSDL (Designer)","right":"Xác định cấu trúc dữ liệu, ràng buộc và mô hình ERD"},{"left":"Lập trình viên ứng dụng","right":"Viết mã truy xuất dữ liệu qua câu lệnh SQL và API"},{"left":"Người dùng cuối (End-user)","right":"Thao tác với dữ liệu qua giao diện ứng dụng hoàn chỉnh"}]}', 'Mỗi nhóm đối tượng có trách nhiệm và mức quyền hạn khác nhau trong vòng đời CSDL.', 2),
('q_csdl_01_s2_05', 'moc_csdl_01_01', 2, 'HIEU', 'SAP_XEP_CAU', 'Chạm vào các từ theo đúng thứ tự để tạo thành câu hoàn chỉnh:', NULL, NULL, NULL, NULL, NULL, '{"prompt":"Giải thích vì sao DBMS giúp giảm dư thừa dữ liệu:","correct_order":["DBMS tập trung dữ liệu","vào một nơi duy nhất","tránh trùng lặp thông tin","giữa các phòng ban"],"distractors":["phân mảnh tệp tin","xóa hết tài liệu"]}', 'Tập trung hóa dữ liệu trong DBMS là giải pháp căn bản để loại bỏ dư thừa không cần thiết.', 2),
('q_csdl_01_s2_06', 'moc_csdl_01_01', 2, 'NHO', 'TRAC_NGHIEM_4', 'Lợi ích cốt lõi của tính năng Kiểm soát Đồng thời (Concurrency Control) trong DBMS là gì?', 'Cho phép nhiều giao dịch truy cập cùng lúc mà vẫn đảm bảo tính chính xác của dữ liệu.', 'Ngăn chặn hoàn toàn việc người dùng truy cập vào cơ sở dữ liệu trong giờ cao điểm.', 'Tự động xóa các bản ghi cũ khi dung lượng bộ nhớ đệm đạt đến ngưỡng tám mươi phần trăm.', 'Tăng tốc độ đọc ghi dữ liệu trên đĩa bằng cách bỏ qua các ràng buộc khóa ngoại đã tạo.', 0, NULL, 'Kiểm soát đồng thời cho phép đa truy cập an toàn mà không gây xung đột hay hỏng dữ liệu.', 2),
('q_csdl_01_s2_07', 'moc_csdl_01_01', 2, 'NHO', 'DIEN_TU', 'Chọn từ thích hợp từ ngân hàng từ bên dưới để điền vào chỗ trống:', NULL, NULL, NULL, NULL, NULL, '{"sentence_template":"Từ điển dữ liệu (Data Dictionary hay System Catalog) chứa {blank}, tức là dữ liệu mô tả về chính cấu trúc của dữ liệu.","blank_answer":"siêu dữ liệu (metadata)","options":["siêu dữ liệu (metadata)","tệp nhị phân rỗng","mã độc gián điệp","bản ghi tạm thời"]}', 'Metadata là dữ liệu mô tả cấu trúc, kiểu dữ liệu, quan hệ và ràng buộc của CSDL.', 2),
('q_csdl_01_s2_08', 'moc_csdl_01_01', 2, 'HIEU', 'TRAC_NGHIEM_4', 'Khi quản trị viên cơ sở dữ liệu thay đổi kiểu chỉ mục từ Hash Index sang B-Tree Index, loại độc lập dữ liệu nào được thể hiện?', 'Độc lập dữ liệu vật lý (Physical Data Independence).', 'Độc lập dữ liệu logic (Logical Data Independence).', 'Độc lập giao diện người dùng (UI Independence).', 'Độc lập giao thức truyền thông mạng (Network Independence).', 0, NULL, 'Chỉ mục (Index) thuộc mức trong (vật lý), đổi chỉ mục không làm đổi bảng logic là độc lập vật lý.', 2),
('q_csdl_01_s3_01', 'moc_csdl_01_01', 3, 'NHO', 'NOI_CAP', 'Nối các thành phần kiến trúc DBMS với nhiệm vụ chuyên trách tương ứng:', NULL, NULL, NULL, NULL, NULL, '{"pairs":[{"left":"Bộ tối ưu truy vấn (Query Optimizer)","right":"Lựa chọn kế hoạch thực thi hiệu quả với chi phí tối ưu"},{"left":"Bộ quản lý bộ đệm (Buffer Manager)","right":"Điều phối việc chuyển nạp trang dữ liệu giữa RAM và đĩa"},{"left":"Bộ quản lý giao dịch (Transaction Manager)","right":"Bảo đảm tính nguyên tử và cô lập khi thao tác đồng thời"},{"left":"Bộ quản lý phục hồi (Recovery Manager)","right":"Khôi phục CSDL về trạng thái nhất quán sau sự cố"}]}', 'Kiến trúc hạt nhân DBMS phân chia rõ ràng trách nhiệm để đạt hiệu năng và độ tin cậy tối đa.', 2),
('q_csdl_01_s3_02', 'moc_csdl_01_01', 3, 'HIEU', 'TRAC_NGHIEM_4', 'Trong ngân hàng, thao tác chuyển khoản gồm trừ tiền tài khoản A và cộng tiền tài khoản B. Tính chất ACID nào bảo đảm cả hai phải cùng thành công hoặc cùng bị hủy bỏ?', 'Tính Nguyên tử (Atomicity).', 'Tính Nhất quán (Consistency).', 'Tính Cô lập (Isolation).', 'Tính Bền vững (Durability).', 0, NULL, 'Tính nguyên tử (Atomicity - All or Nothing) bảo đảm giao dịch không bao giờ thực hiện dang dở.', 2),
('q_csdl_01_s3_03', 'moc_csdl_01_01', 3, 'NHO', 'DIEN_TU', 'Chọn từ thích hợp từ ngân hàng từ bên dưới để điền vào chỗ trống:', NULL, NULL, NULL, NULL, NULL, '{"sentence_template":"Cơ chế ghi nhật ký trước {blank} bảo đảm mọi thay đổi phải được ghi xuống đĩa nhật ký trước khi cập nhật vào tệp CSDL chính.","blank_answer":"WAL (Write-Ahead Logging)","options":["WAL (Write-Ahead Logging)","RAM Cache Buffer","DNS Round Robin","RAID Mirroring"]}', 'Giao thức WAL là nền tảng cốt lõi giúp DBMS phục hồi dữ liệu an toàn sau khi sập nguồn.', 2),
('q_csdl_01_s3_04', 'moc_csdl_01_01', 3, 'HIEU', 'SAP_XEP_CAU', 'Chạm vào các thẻ từ theo đúng thứ tự từ mức người dùng xuống mức thiết bị vật lý:', NULL, NULL, NULL, NULL, NULL, '{"prompt":"Sắp xếp chiều trừu tượng dữ liệu từ trên xuống dưới:","correct_order":["Mức Ngoài (Khung nhìn)","-> Mức Quan niệm (Logic)","-> Mức Trong (Vật lý)","-> Thiết bị đĩa lưu trữ"],"distractors":["-> Mạng Internet","-> Cổng USB"]}', 'Mức ngoài gần người dùng nhất, mức trong tiếp xúc trực tiếp với khối lưu trữ đĩa.', 2),
('q_csdl_01_s3_05', 'moc_csdl_01_01', 3, 'VAN_DUNG', 'TRAC_NGHIEM_4', 'Một lập trình viên tạo thêm View (Khung nhìn) chỉ cho nhân viên kế toán xem cột Luong mà không xem được thông tin khác. Thao tác này can thiệp vào mức nào?', 'Mức Ngoài (External Level).', 'Mức Trong (Internal Level).', 'Mức Vật lý (Physical Level).', 'Mức Phần cứng (Hardware Level).', 0, NULL, 'Tạo View giới hạn cho nhóm người dùng chuyên biệt là xây dựng lược đồ mức ngoài.', 3),
('q_csdl_01_s3_06', 'moc_csdl_01_01', 3, 'HIEU', 'TRAC_NGHIEM_4', 'Tình huống nào sau đây thể hiện rõ hiện tượng Đọc bẩn (Dirty Read) vi phạm tính cô lập dữ liệu?', 'Giao dịch B đọc được dữ liệu tạm thời chưa được commit của giao dịch A.', 'Giao dịch A ghi dữ liệu thành công và đã nhận được thông báo commit.', 'Giao dịch B thực hiện đọc dữ liệu hai lần liên tiếp và đều ra cùng kết quả.', 'Hai giao dịch cùng đọc một bảng dữ liệu nhưng không có giao dịch nào sửa.', 0, NULL, 'Đọc bẩn xảy ra khi giao dịch đọc phải dữ liệu mà giao dịch khác chưa chắc chắn commit (có thể bị rollback).', 2),
('q_csdl_01_s4_01', 'moc_csdl_01_01', 4, 'HIEU', 'SAP_XEP_CAU', 'Chạm vào các từ để tạo thành câu kết luận phân tích về Độc lập Dữ liệu Logic:', NULL, NULL, NULL, NULL, NULL, '{"prompt":"Ghép câu phân tích bản chất Độc lập Dữ liệu Logic:","correct_order":["Lược đồ mức quan niệm","có thể mở rộng thêm cột","mà người dùng mức ngoài","hoàn toàn không bị ảnh hưởng"],"distractors":["phải xóa sạch bảng","dừng hoạt động máy chủ"]}', 'Độc lập logic cách ly ứng dụng khỏi sự thay đổi cấu trúc của toàn bộ hệ thống.', 3),
('q_csdl_01_s4_02', 'moc_csdl_01_01', 4, 'VAN_DUNG', 'TRAC_NGHIEM_4', 'Doanh nghiệp thay thế toàn bộ ổ cứng HDD bằng SSD và thay đổi cấu trúc bảng phân đoạn khối đĩa. Nhận định nào sau đây là CHÍNH XÁC NHẤT?', 'Chỉ có Mức Trong thay đổi; Mức Quan niệm và các chương trình ứng dụng mức ngoài giữ nguyên.', 'Bắt buộc phải viết lại toàn bộ mã nguồn các ứng dụng web và di động kết nối vào cơ sở dữ liệu.', 'Tất cả các bảng dữ liệu, khóa chính và khóa ngoại phải được định nghĩa lại từ đầu bằng DDL.', 'Cơ sở dữ liệu sẽ mất toàn bộ tính độc lập dữ liệu và buộc phải hạ cấp về hệ thống tệp truyền thống.', 0, NULL, 'Thay đổi phần cứng và cách lưu trữ vật lý được cô lập hoàn toàn tại mức trong nhờ tính độc lập vật lý.', 3),
('q_csdl_01_s4_03', 'moc_csdl_01_01', 4, 'HIEU', 'NOI_CAP', 'Nối các hiện tượng bất thường khi không kiểm soát đồng thời với định nghĩa:', NULL, NULL, NULL, NULL, NULL, '{"pairs":[{"left":"Đọc bẩn (Dirty Read)","right":"Đọc dữ liệu chưa commit của giao dịch khác"},{"left":"Mất cập nhật (Lost Update)","right":"Hai giao dịch cùng ghi đè làm mất thao tác"},{"left":"Không lặp lại được","right":"Đọc cùng dòng 2 lần cho 2 giá trị khác nhau"},{"left":"Bóng ma (Phantom Read)","right":"Truy vấn lại xuất hiện thêm các dòng mới chèn"}]}', 'Các mức cô lập (Read Committed, Repeatable Read, Serializable) được thiết kế để khắc phục lần lượt các hiện tượng này.', 3),
('q_csdl_01_s4_04', 'moc_csdl_01_01', 4, 'NHO', 'DIEN_TU', 'Chọn từ thích hợp từ ngân hàng từ bên dưới để điền vào chỗ trống:', NULL, NULL, NULL, NULL, NULL, '{"sentence_template":"Để ngăn ngừa dị thường Đọc bẩn, chuẩn SQL quy định mức cô lập tối thiểu cần áp dụng là {blank}.","blank_answer":"READ COMMITTED","options":["READ COMMITTED","READ UNCOMMITTED","NO LOCK","DIRTY WRITE"]}', 'Mức READ COMMITTED chỉ cho phép đọc dữ liệu đã được commit chính thức.', 2),
('q_csdl_01_s4_05', 'moc_csdl_01_01', 4, 'VAN_DUNG', 'TRAC_NGHIEM_4', 'Máy chủ sập nguồn khi lệnh COMMIT vừa gửi thành công nhưng dữ liệu chưa kịp ghi xuống đĩa. DBMS làm gì khi khởi động lại?', 'Sử dụng nhật ký REDO để ghi lại các thay đổi của giao dịch đã commit lên đĩa dữ liệu.', 'Tự động hủy bỏ giao dịch và trả lại thông báo lỗi yêu cầu khách hàng thực hiện lại từ đầu.', 'Xóa toàn bộ tệp cơ sở dữ liệu vì cấu trúc bảng đã bị tổn hại nghiêm trọng không thể phục hồi.', 'Bỏ qua lỗi và để mặc cho số dư tài khoản của khách hàng không khớp với số tiền thực tế đã rút.', 0, NULL, 'Giao dịch đã commit thì tính bền vững (Durability) yêu cầu dùng bản ghi REDO trong nhật ký WAL để hoàn tất cập nhật.', 3),
('q_csdl_02_s1_01', 'moc_csdl_02_01', 1, 'NHO', 'TRAC_NGHIEM_4', 'Trong mô hình dữ liệu quan hệ, một Quan hệ (Relation) tương ứng với khái niệm nào trong thực tế triển khai bảng?', 'Một bảng dữ liệu 2 chiều gồm các dòng và cột có cấu trúc xác định.', 'Một con trỏ chỉ mục trỏ đến một vị trí byte trên thiết bị đĩa cứng.', 'Một câu lệnh truy vấn viết bằng ngôn ngữ lập trình Java hoặc C#.', 'Một thư mục chứa các tệp văn bản phi cấu trúc trên hệ điều hành.', 0, NULL, 'Quan hệ trong mô hình quan hệ là một bảng 2 chiều gồm các hàng (bộ) và cột (thuộc tính).', 1),
('q_csdl_02_s1_02', 'moc_csdl_02_01', 1, 'NHO', 'TRAC_NGHIEM_4', 'Khái niệm "Bộ" (Tuple) trong mô hình dữ liệu quan hệ tương đương với thành phần nào trong bảng?', 'Một hàng (dòng dữ liệu) đại diện cho một cá thể đối tượng cụ thể.', 'Một cột (thuộc tính) mô tả đặc tính của tập hợp các đối tượng.', 'Tiêu đề của toàn bộ bảng được định nghĩa trong câu lệnh tạo bảng.', 'Tệp nhật ký ghi lại các thao tác thay đổi dữ liệu của giao dịch.', 0, NULL, 'Bộ (Tuple) là một dòng dữ liệu chứa các giá trị thuộc tính của một đối tượng đơn lẻ.', 1),
('q_csdl_02_s1_03', 'moc_csdl_02_01', 1, 'NHO', 'DIEN_TU', 'Chọn từ thích hợp từ ngân hàng từ bên dưới để điền vào chỗ trống:', NULL, NULL, NULL, NULL, NULL, '{"sentence_template":"Tập hợp tất cả các giá trị hợp lệ mà một thuộc tính có thể nhận được gọi là {blank} của thuộc tính.","blank_answer":"miền giá trị (Domain)","options":["miền giá trị (Domain)","khóa chính (Primary Key)","bộ (Tuple)","quan hệ (Relation)"]}', 'Miền giá trị (Domain) quy định kiểu dữ liệu và giới hạn giá trị của một thuộc tính.', 1),
('q_csdl_02_s1_04', 'moc_csdl_02_01', 1, 'NHO', 'NOI_CAP', 'Hãy nối các thuật ngữ trong mô hình quan hệ với thuật ngữ bảng CSDL tương đương:', NULL, NULL, NULL, NULL, NULL, '{"pairs":[{"left":"Quan hệ (Relation)","right":"Bảng (Table)"},{"left":"Bộ (Tuple)","right":"Hàng (Row / Record)"},{"left":"Thuộc tính (Attribute)","right":"Cột (Column / Field)"},{"left":"Bậc của quan hệ (Degree)","right":"Số lượng thuộc tính (cột) trong bảng"}]}', 'Đây là các thuật ngữ cơ bản đối sánh giữa lý thuyết quan hệ và cơ sở dữ liệu quan hệ thực tế.', 1),
('q_csdl_02_s1_05', 'moc_csdl_02_01', 1, 'NHO', 'SAP_XEP_CAU', 'Chạm vào các thẻ từ theo đúng thứ tự để tạo thành quy tắc Toàn vẹn Thực thể:', NULL, NULL, NULL, NULL, NULL, '{"prompt":"Ghép quy tắc Toàn vẹn Thực thể (Entity Integrity):","correct_order":["Không có bất kỳ thuộc tính nào","thuộc khóa chính","được phép mang","giá trị NULL"],"distractors":["được mang số nguyên","phải là khóa ngoại"]}', 'Toàn vẹn thực thể yêu cầu khóa chính phải phân biệt duy nhất từng cá thể, do đó không được NULL.', 1),
('q_csdl_02_s2_01', 'moc_csdl_02_01', 2, 'HIEU', 'TRAC_NGHIEM_4', 'Điểm khác biệt cốt lõi giữa Khóa Ứng Viên (Candidate Key) và Siêu Khóa (Super Key) là gì?', 'Khóa ứng viên là một siêu khóa tối thiểu, không thể bỏ bớt thuộc tính nào mà vẫn là khóa.', 'Khóa ứng viên luôn chứa nhiều thuộc tính hơn so với bất kỳ siêu khóa nào trong bảng.', 'Khóa ứng viên được phép mang giá trị NULL còn siêu khóa thì tuyệt đối không được phép.', 'Khóa ứng viên chỉ được định nghĩa trên bảng phụ còn siêu khóa chỉ tồn tại ở bảng chính.', 0, NULL, 'Khóa ứng viên là siêu khóa tối thiểu (Minimal Superkey).', 2),
('q_csdl_02_s2_02', 'moc_csdl_02_01', 2, 'HIEU', 'TRAC_NGHIEM_4', 'Ràng buộc Toàn vẹn Tham chiếu (Referential Integrity Constraint) quy định điều gì đối với Khóa Ngoại?', 'Giá trị khóa ngoại phải khớp với một giá trị khóa chính đang tồn tại hoặc phải mang giá trị NULL.', 'Khóa ngoại bắt buộc phải có tên gọi hoàn toàn giống với tên của khóa chính được tham chiếu.', 'Mỗi bảng dữ liệu chỉ được phép chứa tối đa một khóa ngoại duy nhất liên kết với bảng cha.', 'Khóa ngoại phải được tạo trước khi bảng chứa khóa chính được định nghĩa trong hệ thống.', 0, NULL, 'Khóa ngoại không được trỏ đến một giá trị không tồn tại ở bảng tham chiếu.', 2),
('q_csdl_02_s2_03', 'moc_csdl_02_01', 2, 'NHO', 'NOI_CAP', 'Nối các loại khóa trong CSDL quan hệ với định nghĩa chính xác:', NULL, NULL, NULL, NULL, NULL, '{"pairs":[{"left":"Khóa chính (Primary Key)","right":"Khóa ứng viên được chọn làm định danh chính, cấm NULL"},{"left":"Khóa ngoại (Foreign Key)","right":"Tham chiếu đến khóa chính hoặc khóa duy nhất bảng khác"},{"left":"Khóa phức hợp (Composite Key)","right":"Khóa được ghép từ hai hoặc nhiều thuộc tính"},{"left":"Khóa nhân tạo (Surrogate Key)","right":"Khóa tự sinh (Auto Increment/UUID) không có ý nghĩa nghiệp vụ"}]}', 'Hiểu đúng các loại khóa là điều kiện tiên quyết để thiết kế CSDL chuẩn xác.', 2),
('q_csdl_02_s2_04', 'moc_csdl_02_01', 2, 'HIEU', 'DIEN_TU', 'Chọn từ thích hợp từ ngân hàng từ bên dưới để điền vào chỗ trống:', NULL, NULL, NULL, NULL, NULL, '{"sentence_template":"Trong mô hình ERD, mối quan hệ nhiều - nhiều (N - N) giữa hai thực thể khi chuyển sang mô hình quan hệ bắt buộc phải tạo thành một {blank}.","blank_answer":"bảng liên kết trung gian","options":["bảng liên kết trung gian","thuộc tính đa trị","khóa chính độc lập","chỉ mục phức hợp"]}', 'Quan hệ N-N được chuyển thành bảng trung gian (Junction table) chứa 2 khóa ngoại tham chiếu.', 2),
('q_csdl_02_s3_01', 'moc_csdl_02_01', 3, 'VAN_DUNG', 'TRAC_NGHIEM_4', 'Giả sử có bảng SinhVien(MaSV, Email, CCCD, HoTen). Trong đó MaSV, Email, CCCD đều là duy nhất và tối thiểu. Bảng này có bao nhiêu Khóa Ứng Viên?', '3 khóa ứng viên (MaSV, Email, CCCD).', '1 khóa ứng viên duy nhất (chỉ có MaSV).', '4 khóa ứng viên bao gồm cả cột HoTen.', '0 khóa ứng viên vì chưa chỉ định khóa chính.', 0, NULL, 'Cả 3 thuộc tính đều là siêu khóa tối thiểu, do đó đều là khóa ứng viên (Candidate Keys).', 2),
('q_csdl_02_s3_02', 'moc_csdl_02_01', 3, 'HIEU', 'SAP_XEP_CAU', 'Chạm vào các thẻ từ theo đúng thứ tự để tạo thành câu hoàn chỉnh:', NULL, NULL, NULL, NULL, NULL, '{"prompt":"Quy tắc chuyển đổi mối quan hệ 1 - N sang mô hình quan hệ:","correct_order":["Lấy khóa chính bên 1","đưa sang làm khóa ngoại","tại bảng bên N","để tạo liên kết"],"distractors":["tách thành ba bảng","xóa bỏ bảng bên N"]}', 'Quan hệ 1-N được ánh xạ bằng cách đưa PK của bên 1 sang làm FK ở bên N.', 2),
('q_csdl_02_s3_03', 'moc_csdl_02_01', 3, 'NHO', 'NOI_CAP', 'Nối các hành vi kích hoạt khi xóa khóa ngoại (ON DELETE Action) với ý nghĩa tương ứng:', NULL, NULL, NULL, NULL, NULL, '{"pairs":[{"left":"CASCADE","right":"Tự động xóa các bản ghi con tham chiếu khi bản ghi cha bị xóa"},{"left":"RESTRICT / NO ACTION","right":"Từ chối thao tác xóa cha nếu vẫn còn bản ghi con tham chiếu"},{"left":"SET NULL","right":"Đặt giá trị khóa ngoại ở bản ghi con thành NULL khi cha bị xóa"},{"left":"SET DEFAULT","right":"Gán giá trị mặc định cho khóa ngoại ở con khi cha bị xóa"}]}', 'Các tùy chọn ON DELETE duy trì tính toàn vẹn tham chiếu tự động.', 2),
('q_csdl_02_s4_01', 'moc_csdl_02_01', 4, 'VAN_DUNG', 'TRAC_NGHIEM_4', 'Cho bảng KetQua(MaSV, MaMH, Diem). Khóa chính là tập hợp (MaSV, MaMH). Thuộc tính Diem phụ thuộc vào thành phần nào?', 'Phụ thuộc hàm đầy đủ vào toàn bộ khóa chính phức hợp (MaSV, MaMH).', 'Chỉ phụ thuộc vào MaSV vì sinh viên là đối tượng chính nhận điểm.', 'Chỉ phụ thuộc vào MaMH vì mỗi môn học có mức độ khó khác nhau.', 'Không phụ thuộc vào bất kỳ thuộc tính nào trong lược đồ quan hệ.', 0, NULL, 'Điểm số của một sinh viên chỉ xác định khi biết cả sinh viên đó VÀ môn học cụ thể.', 3),
('q_csdl_02_s4_02', 'moc_csdl_02_01', 4, 'HIEU', 'SAP_XEP_CAU', 'Chạm vào các thẻ từ để tạo thành câu hoàn chỉnh:', NULL, NULL, NULL, NULL, NULL, '{"prompt":"Quy tắc xác định khóa chính tối ưu cho bảng dữ liệu:","correct_order":["Khóa chính nên là","giá trị ngắn gọn, bất biến,","không chứa thông tin nhạy cảm","và đảm bảo tính duy nhất"],"distractors":["thường xuyên thay đổi","dài tối đa"]}', 'Khóa chính tối ưu cần ổn định, ngắn gọn để tăng tốc index và hạn chế cập nhật cascade.', 3),
('q_csdl_03_s1_01', 'moc_csdl_03_01', 1, 'NHO', 'TRAC_NGHIEM_4', 'Tập hợp các câu lệnh nào sau đây thuộc nhóm DDL (Data Definition Language) trong SQL?', 'CREATE, ALTER, DROP, TRUNCATE dùng để định nghĩa cấu trúc bảng.', 'SELECT, INSERT, UPDATE, DELETE dùng để thao tác trên dữ liệu.', 'GRANT, REVOKE, DENY dùng để phân quyền bảo mật người dùng.', 'COMMIT, ROLLBACK, SAVEPOINT dùng để kiểm soát giao dịch an toàn.', 0, NULL, 'DDL quản lý cấu trúc bảng, lược đồ và chỉ mục (CREATE, ALTER, DROP, TRUNCATE).', 1),
('q_csdl_03_s1_02', 'moc_csdl_03_01', 1, 'NHO', 'NOI_CAP', 'Nối các nhóm câu lệnh SQL với chức năng cốt lõi tương ứng:', NULL, NULL, NULL, NULL, NULL, '{"pairs":[{"left":"DDL (Data Definition Language)","right":"Tạo lập, sửa đổi cấu trúc bảng và lược đồ (CREATE, ALTER, DROP)"},{"left":"DML (Data Manipulation Language)","right":"Truy vấn, thêm mới, cập nhật và xóa dữ liệu (SELECT, INSERT, UPDATE)"},{"left":"DCL (Data Control Language)","right":"Cấp quyền và thu hồi quyền hạn bảo mật (GRANT, REVOKE)"},{"left":"TCL (Transaction Control Language)","right":"Xác nhận hoặc hoàn tác giao dịch dữ liệu (COMMIT, ROLLBACK)"}]}', 'SQL được phân chia thành 4 phân nhánh ngôn ngữ rõ rệt.', 1),
('q_csdl_03_s1_03', 'moc_csdl_03_01', 1, 'NHO', 'DIEN_TU', 'Chọn từ thích hợp từ ngân hàng từ bên dưới để điền vào chỗ trống:', NULL, NULL, NULL, NULL, NULL, '{"sentence_template":"Phép kết bảng {blank} chỉ trả về những dòng có giá trị tương ứng ở cả hai bảng kết nối.","blank_answer":"INNER JOIN","options":["INNER JOIN","FULL OUTER JOIN","CROSS JOIN","LEFT JOIN"]}', 'INNER JOIN là phép kết trong, chỉ giữ lại các dòng khớp khóa ở cả hai phía.', 1),
('q_csdl_03_s1_04', 'moc_csdl_03_01', 1, 'NHO', 'SAP_XEP_CAU', 'Chạm vào các từ theo đúng thứ tự logic thực thi truy vấn của SQL Engine:', NULL, NULL, NULL, NULL, NULL, '{"prompt":"Thứ tự thực thi logic của câu lệnh SELECT:","correct_order":["FROM & JOIN","-> WHERE","-> GROUP BY","-> HAVING","-> SELECT","-> ORDER BY"],"distractors":["-> COMMIT","-> DROP TABLE"]}', 'Trình tối ưu SQL luôn xác định nguồn dữ liệu (FROM) trước khi lọc (WHERE) và gom nhóm (GROUP BY).', 1),
('q_csdl_03_s2_01', 'moc_csdl_03_01', 2, 'HIEU', 'TRAC_NGHIEM_4', 'Sự khác biệt căn bản giữa mệnh đề WHERE và HAVING trong SQL là gì?', 'WHERE lọc từng dòng trước khi gom nhóm; HAVING lọc trên kết quả tổng hợp sau GROUP BY.', 'WHERE chỉ sử dụng cho các bảng đơn lẻ; HAVING chỉ dùng khi thực hiện liên kết nhiều bảng.', 'WHERE bắt buộc phải đi cùng các hàm gộp; HAVING nghiêm cấm sử dụng các hàm toán học.', 'WHERE và HAVING hoàn toàn đồng nghĩa và có thể thay thế cho nhau trong mọi câu lệnh.', 0, NULL, 'WHERE áp dụng lọc trên từng bộ dữ liệu thô, còn HAVING lọc trên các nhóm sau khi gom nhóm.', 2),
('q_csdl_03_s2_02', 'moc_csdl_03_01', 2, 'HIEU', 'NOI_CAP', 'Nối các loại phép kết bảng JOIN với tập kết quả trả về:', NULL, NULL, NULL, NULL, NULL, '{"pairs":[{"left":"INNER JOIN","right":"Chỉ trả về các dòng khớp điều kiện ở cả hai bảng"},{"left":"LEFT JOIN","right":"Giữ toàn bộ dòng bảng trái, ghép bên phải (nếu thiếu điền NULL)"},{"left":"RIGHT JOIN","right":"Giữ toàn bộ dòng bảng phải, ghép bên trái (nếu thiếu điền NULL)"},{"left":"FULL OUTER JOIN","right":"Giữ lại toàn bộ dòng của cả hai bảng, thiếu bên nào điền NULL"}]}', 'Mỗi loại JOIN quyết định cách xử lý các bản ghi không khớp khóa giữa hai bảng.', 2),
('q_csdl_03_s2_03', 'moc_csdl_03_01', 2, 'HIEU', 'DIEN_TU', 'Chọn từ thích hợp từ ngân hàng từ bên dưới để điền vào chỗ trống:', NULL, NULL, NULL, NULL, NULL, '{"sentence_template":"Muốn đếm số lượng sinh viên duy nhất trong từng lớp học, câu lệnh cần dùng là COUNT({blank} MaSV).","blank_answer":"DISTINCT","options":["DISTINCT","ALL","UNIQUE","PRIMARY"]}', 'Từ khóa DISTINCT loại bỏ các giá trị trùng lặp trước khi hàm COUNT thực hiện tính toán.', 2),
('q_csdl_03_s3_01', 'moc_csdl_03_01', 3, 'VAN_DUNG', 'TRAC_NGHIEM_4', 'Bảng NhanVien có 10 dòng, bảng PhongBan có 3 dòng. Một câu truy vấn CROSS JOIN giữa hai bảng này sẽ trả về chính xác bao nhiêu dòng kết quả?', '30 dòng kết quả (tích đề-các của 10 và 3).', '13 dòng kết quả (tổng số lượng của cả hai bảng).', '10 dòng kết quả (lấy theo số dòng của bảng lớn nhất).', '0 dòng kết quả nếu không có điều kiện khóa ngoại.', 0, NULL, 'CROSS JOIN tạo tích Cartesian (10 x 3 = 30 dòng).', 2),
('q_csdl_03_s3_02', 'moc_csdl_03_01', 3, 'HIEU', 'SAP_XEP_CAU', 'Chạm vào các thẻ từ để tạo thành câu truy vấn chuẩn đếm số sinh viên theo khoa có trên 50 người:', NULL, NULL, NULL, NULL, NULL, '{"prompt":"Ghép thứ tự câu lệnh truy vấn lọc nhóm:","correct_order":["SELECT MaKhoa, COUNT(MaSV)","FROM SinhVien","GROUP BY MaKhoa","HAVING COUNT(MaSV) > 50"],"distractors":["WHERE COUNT(MaSV) > 50","ORDER BY NULL"]}', 'Hàm COUNT(MaSV) > 50 bắt buộc phải đặt trong mệnh đề HAVING vì là điều kiện trên nhóm.', 3),
('q_csdl_03_s4_01', 'moc_csdl_03_01', 4, 'VAN_DUNG', 'TRAC_NGHIEM_4', 'Lệnh DELETE FROM NhanVien khác biệt cơ bản như thế nào so với lệnh TRUNCATE TABLE NhanVien?', 'DELETE ghi log từng dòng và có thể kích hoạt Trigger; TRUNCATE giải phóng toàn bộ trang đĩa nhanh hơn.', 'DELETE xóa toàn bộ cấu trúc bảng khỏi cơ sở dữ liệu; TRUNCATE chỉ xóa các dữ liệu có chứa giá trị NULL.', 'TRUNCATE yêu cầu quyền truy cập của người dùng cuối; DELETE chỉ dành riêng cho tài khoản quản trị hệ thống.', 'Cả hai lệnh hoàn toàn giống hệt nhau về cả cơ chế ghi nhật ký lẫn tốc độ giải phóng khối lưu trữ vật lý.', 0, NULL, 'TRUNCATE là lệnh DDL giải phóng trang bộ nhớ và reset identity, trong khi DELETE là lệnh DML ghi log từng dòng.', 3),
('q_csdl_04_s1_01', 'moc_csdl_04_01', 1, 'NHO', 'TRAC_NGHIEM_4', 'Mục đích tối thượng của quá trình Chuẩn hóa Cơ sở Dữ liệu (Normalization) là gì?', 'Khử dư thừa dữ liệu và ngăn ngừa các dị thường khi thêm, xóa, sửa.', 'Tăng kích thước tệp cơ sở dữ liệu để tận dụng tối đa dung lượng ổ đĩa.', 'Giảm số lượng bảng dữ liệu xuống mức tối thiểu (chỉ còn duy nhất một bảng).', 'Tự động mã hóa toàn bộ dữ liệu người dùng bằng các giải thuật mật mã đối xứng.', 0, NULL, 'Chuẩn hóa giúp loại bỏ dư thừa và triệt tiêu các dị thường thêm, sửa, xóa (Anomalies).', 1),
('q_csdl_04_s1_02', 'moc_csdl_04_01', 1, 'NHO', 'DIEN_TU', 'Chọn từ thích hợp từ ngân hàng từ bên dưới để điền vào chỗ trống:', NULL, NULL, NULL, NULL, NULL, '{"sentence_template":"Một quan hệ đạt Dạng chuẩn 1 (1NF) khi tất cả các thuộc tính đều chứa giá trị {blank}, không có thuộc tính đa trị hay thuộc tính lặp.","blank_answer":"nguyên tố (Atomic)","options":["nguyên tố (Atomic)","phức hợp","mảng danh sách","chuỗi JSON"]}', '1NF yêu cầu mọi miền giá trị đều là giá trị nguyên tử (Atomic values).', 1),
('q_csdl_04_s1_03', 'moc_csdl_04_01', 1, 'NHO', 'NOI_CAP', 'Hãy nối các Dạng chuẩn CSDL với điều kiện tiên quyết cần đạt được:', NULL, NULL, NULL, NULL, NULL, '{"pairs":[{"left":"Dạng chuẩn 1 (1NF)","right":"Mọi giá trị thuộc tính đều là nguyên tố (Atomic), không có lặp"},{"left":"Dạng chuẩn 2 (2NF)","right":"Đạt 1NF và không tồn tại phụ thuộc hàm một phần vào khóa chính"},{"left":"Dạng chuẩn 3 (3NF)","right":"Đạt 2NF và không tồn tại phụ thuộc hàm bắc cầu qua thuộc tính không khóa"},{"left":"Dạng chuẩn BCNF","right":"Mọi phụ thuộc hàm X -> Y thì X đều bắt buộc phải là một siêu khóa"}]}', 'Các dạng chuẩn tạo thành một chuỗi kế thừa nghiêm ngặt (1NF -> 2NF -> 3NF -> BCNF).', 1),
('q_csdl_04_s2_01', 'moc_csdl_04_01', 2, 'HIEU', 'TRAC_NGHIEM_4', 'Nếu một bảng đã đạt chuẩn 1NF và Khóa chính của bảng chỉ gồm DUY NHẤT MỘT THUỘC TÍNH (khóa đơn), bảng đó có tự động đạt 2NF không?', 'Chắc chắn đạt 2NF vì không thể tồn tại phụ thuộc một phần vào một khóa đơn.', 'Không bao giờ đạt 2NF vì khóa đơn luôn tạo ra các phụ thuộc hàm dư thừa.', 'Chỉ đạt 2NF khi bảng chứa ít hơn mười dòng dữ liệu trong thực tế triển khai.', 'Tùy thuộc vào việc bảng đó có chứa các trường kiểu văn bản hay kiểu số nguyên.', 0, NULL, 'Phụ thuộc một phần chỉ xảy ra khi khóa chính là khóa phức hợp gồm từ 2 thuộc tính trở lên.', 2),
('q_csdl_04_s2_02', 'moc_csdl_04_01', 2, 'HIEU', 'SAP_XEP_CAU', 'Chạm vào các thẻ từ để tạo thành câu hoàn chỉnh về điều kiện 3NF:', NULL, NULL, NULL, NULL, NULL, '{"prompt":"Quy tắc đạt Dạng chuẩn 3 (3NF):","correct_order":["Bảng phải đạt 2NF","và mọi thuộc tính không khóa","phải phụ thuộc trực tiếp","vào khóa chính"],"distractors":["phụ thuộc bắc cầu","không cần có khóa"]}', '3NF triệt tiêu hoàn toàn hiện tượng phụ thuộc hàm bắc cầu qua các thuộc tính không khóa.', 2),
('q_csdl_04_s3_01', 'moc_csdl_04_01', 3, 'VAN_DUNG', 'TRAC_NGHIEM_4', 'Cho quan hệ DonHang(MaDH, MaSP, SoLuong, TenSP, DonGia). Khóa chính là (MaDH, MaSP). Biết MaSP -> (TenSP, DonGia). Quan hệ này đang ở dạng chuẩn nào và vi phạm gì?', 'Đạt 1NF nhưng vi phạm 2NF vì TenSP và DonGia phụ thuộc một phần vào MaSP.', 'Đã đạt 3NF vì không có bất kỳ thuộc tính nào mang giá trị trùng lặp trong thực tế.', 'Chưa đạt 1NF vì cột DonGia có thể chứa nhiều giá trị phân cách bằng dấu phẩy.', 'Đạt chuẩn BCNF vì cặp (MaDH, MaSP) đã là một siêu khóa duy nhất của toàn bảng.', 0, NULL, 'TenSP và DonGia chỉ phụ thuộc vào MaSP (một phần của khóa chính), do đó vi phạm 2NF.', 3),
('q_csdl_04_s3_02', 'moc_csdl_04_01', 3, 'HIEU', 'NOI_CAP', 'Nối các loại dị thường dữ liệu với kịch bản phát sinh trong thực tế:', NULL, NULL, NULL, NULL, NULL, '{"pairs":[{"left":"Dị thường Thêm mới (Insertion)","right":"Không thể thêm khoa mới nếu chưa có sinh viên nào theo học"},{"left":"Dị thường Xóa (Deletion)","right":"Xóa sinh viên cuối cùng vô tình làm mất luôn thông tin về khoa"},{"left":"Dị thường Cập nhật (Update)","right":"Đổi trưởng khoa ở một dòng nhưng quên đổi ở các dòng khác"},{"left":"Phân rã bảo toàn thông tin","right":"Ghép tự nhiên các bảng con thu lại chính xác bảng ban đầu"}]}', 'Các dị thường này là bằng chứng rõ ràng chứng minh lược đồ cần được chuẩn hóa.', 3),
('q_csdl_04_s4_01', 'moc_csdl_04_01', 4, 'VAN_DUNG', 'TRAC_NGHIEM_4', 'Để chuẩn hóa quan hệ DonHang(MaDH, MaSP, SoLuong, TenSP, DonGia) vi phạm 2NF ở trên về 2NF, giải pháp chuẩn hóa phân rã lược đồ là gì?', 'Tách thành DonHangChiTiet(MaDH, MaSP, SoLuong) và SanPham(MaSP, TenSP, DonGia).', 'Gộp toàn bộ thông tin khách hàng và ngày đặt hàng vào chung một bảng duy nhất.', 'Xóa bỏ hai cột TenSP và DonGia khỏi cơ sở dữ liệu và nhập trực tiếp khi in hóa đơn.', 'Tạo thêm một bảng trung gian chứa ba khóa ngoại liên kết với ba bảng phụ trợ khác.', 0, NULL, 'Tách các thuộc tính phụ thuộc một phần ra bảng riêng với khóa chính là phần khóa đó.', 3);

